// Resolves the ball against the brick grid. Pure logic: no DOM, no drawing.
// For each brick the ball overlaps it flips the velocity component of the
// axis of SMALLEST penetration (that is the face struck; equal penetrations
// mean a corner and flip both axes), then pushes the ball back out of the
// brick so it can never stick on the next frame.
// Returns nothing; mutates `state`.
export function bounceBricks(state) {
  const { ball } = state;
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const penLeft = ball.x + ball.r - brick.x;
    const penRight = brick.x + brick.w - (ball.x - ball.r);
    const penTop = ball.y + ball.r - brick.y;
    const penBottom = brick.y + brick.h - (ball.y - ball.r);
    const penX = Math.min(penLeft, penRight);
    const penY = Math.min(penTop, penBottom);

    // Face vs corner: the axis of smallest penetration is the face struck.
    if (penX === penY) {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    } else if (penX < penY) {
      ball.vx = -ball.vx;
    } else {
      ball.vy = -ball.vy;
    }

    // Push the ball back out of the brick along the struck face.
    const eps = 0.01;
    if (penX <= penY) {
      ball.x = penLeft < penRight ? brick.x - ball.r - eps : brick.x + brick.w + ball.r + eps;
    }
    if (penY <= penX) {
      ball.y = penTop < penBottom ? brick.y - ball.r - eps : brick.y + brick.h + ball.r + eps;
    }
  }
}

